#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

/**
 * 題目 10429: Contest Scoreboard
 * 實作競賽排名系統：
 * 1. 解題數愈多愈前面。
 * 2. 解題數相同時，罰時愈少愈前面。
 * 3. 以上皆相同時，隊號愈小愈前面。
 * 
 * 罰時計算：
 * 已解決問題的罰時 = 解決該題的時間 + 20 * (在該題通過之前的錯誤提交次數)。
 */

struct Team {
    int id;
    int solved;
    int penalty;
    bool appeared;
    bool problemSolved[10];
    int incorrectCount[10];

    Team(int _id) : id(_id), solved(0), penalty(0), appeared(false) {
        for (int i = 0; i < 10; ++i) {
            problemSolved[i] = false;
            incorrectCount[i] = 0;
        }
    }

    bool operator<(const Team& other) const {
        if (solved != other.solved) return solved > other.solved;
        if (penalty != other.penalty) return penalty < other.penalty;
        return id < other.id;
    }
};

int main() {
    int T;
    string line;
    if (!(cin >> T)) return 0;
    getline(cin, line); // 消耗 T 後的換行
    getline(cin, line); // 消耗第一題之前的空行

    while (T--) {
        vector<Team> teams;
        for (int i = 0; i <= 100; ++i) teams.push_back(Team(i));

        while (getline(cin, line) && !line.empty()) {
            stringstream ss(line);
            int contestant, problem, time;
            char L;
            ss >> contestant >> problem >> time >> L;
            teams[contestant].appeared = true;

            // 如果該題已解決，忽略後續提交
            if (teams[contestant].problemSolved[problem]) continue;

            if (L == 'C') {
                teams[contestant].problemSolved[problem] = true;
                teams[contestant].solved++;
                teams[contestant].penalty += time + teams[contestant].incorrectCount[problem] * 20;
            } else if (L == 'I') {
                teams[contestant].incorrectCount[problem]++;
            }
        }

        vector<Team> result;
        for (int i = 1; i <= 100; ++i) {
            if (teams[i].appeared) result.push_back(teams[i]);
        }
        sort(result.begin(), result.end());

        for (const auto& t : result) {
            cout << t.id << " " << t.solved << " " << t.penalty << endl;
        }
        if (T > 0) cout << endl;
    }
    return 0;
}
